package com.aidomari.app.domain.model

object HokkaidoAct1Route {

    val nodes: List<SugorokuNode> by lazy {
        rawNodes.mapIndexed { index, raw ->
            raw.copy(stepIndex = index)
        }
    }

    val routeNodes: List<SugorokuNode>
        get() = nodes

    val totalNodes: Int
        get() = nodes.size

    val maxStepIndex: Int
        get() = (totalNodes - 1).coerceAtLeast(0)

    val startNode: SugorokuNode
        get() = nodes.first()

    val goalNode: SugorokuNode
        get() = nodes.last()

    fun getNodeByIndex(index: Int): SugorokuNode? =
        nodes.getOrNull(index)

    fun getNodeByStepIndex(stepIndex: Int): SugorokuNode? =
        nodes.getOrNull(stepIndex)

    fun getNodeById(id: String): SugorokuNode? =
        nodes.firstOrNull { it.id == id }

    private val rawNodes: List<SugorokuNode> by lazy {
        buildList(2000) {
            addAll(chunk0())
            addAll(chunk1())
            addAll(chunk2())
            addAll(chunk3())
            addAll(chunk4())
            addAll(chunk5())
            addAll(chunk6())
            addAll(chunk7())
